+    suite('dispatchPlan (UT-1)', function () {
+        test('fork PR + head-targeted dispatch → base machine ref + pull-ref checkout plan (AC1)', function () {
+            var plan = mod.dispatchPlan(BRANCH, forkItem(), BASE_OWNER, BASE_REPO);
