+    });
+
+    suite('classifyForkNoRef (UT-2)', function () {
+        test('a 422 naming a fork branch with a FETCHABLE pull ref is NOT head-dead (AC2)', function () {
+            assert.equal(mod.classifyForkNoRef(true), 'live',
