+        test('an expanded empty ref (no branch to expand) passes through — the caller falls back to main', function () {
+            assert.deepEqual(mod.dispatchPlan('', forkItem(), BASE_OWNER, BASE_REPO),
+                { ref: '', checkoutRef: null });
