    ACTIVE_RUN_STATES: ACTIVE_RUN_STATES,
    STALE_CANCEL_MARKER_RE: STALE_CANCEL_MARKER_RE,
    staleCancelMarkerLine: staleCancelMarkerLine,
    SILENT_UPDATE_MAX_FAILURES: SILENT_UPDATE_MAX_FAILURES,
