+        test('same-repo PR keeps ref:<branch> with NO checkout plan (regression guard)', function () {
+            var plan = mod.dispatchPlan(BRANCH, forkItem({ headRepo: BASE_FULL }), BASE_OWNER, BASE_REPO);
