    classifyTriggerError: classifyTriggerError,
    triggerFailMarks: triggerFailMarks,
    triggerFailMarkerLine: triggerFailMarkerLine,
    capOf: capOf,
    TRIGGER_FAIL_MARKER_RE: TRIGGER_FAIL_MARKER_RE
};

