+        var nextOk = !((next >= '0' && next <= '9') || next === '-');
+        var prevOk = !((prev >= 'a' && prev <= 'z') || (prev >= 'A' && prev <= 'Z') ||
+            (prev >= '0' && prev <= '9') || prev === '-' || prev === '#');
+        if (nextOk && prevOk) return true;
